import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/installation.md","filePath":"ja/guide/installation.md","lastUpdated":1793173149000}`),a={name:`ja/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to “インストール”">​</a></h1><p>Sudoku は App Store でユニバーサルアプリとして提供されており、1 回の購入で iPhone、iPad、Mac に対応します。</p><h2 id="ダウンロード" tabindex="-1">ダウンロード <a class="header-anchor" href="#ダウンロード" aria-label="Permalink to “ダウンロード”">​</a></h2><ul><li><strong>App Store</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">Sudoku をダウンロード</a> — iPhone、iPad、Mac 対応のユニバーサルアプリ</li></ul><h3 id="app-store-推奨" tabindex="-1">App Store（推奨） <a class="header-anchor" href="#app-store-推奨" aria-label="Permalink to “App Store（推奨）”">​</a></h3><p>App Store 版は自動アップデートに対応し、お持ちのすべての Apple デバイスとシームレスに連携します。</p><ul><li><strong>App Store ID</strong>：6793606018</li><li><strong>リンク</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>対応プラットフォーム</strong>：iPhone、iPad、Mac（ユニバーサルアプリ）</li><li><strong>価格</strong>：現在の価格は App Store の掲載情報をご確認ください</li></ul><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to “インストール手順”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>デバイスで <strong>App Store</strong> を開きます</li><li>「Sudoku」を検索するか、上記の直接リンクを使用します</li><li><strong>入手</strong> または <strong>購入</strong> をタップしてダウンロードします</li><li>アプリは自動的にインストールされます</li><li>ホーム画面から Sudoku を起動します</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Mac で <strong>App Store</strong> を開きます</li><li>「Sudoku」を検索するか、上記の直接リンクを使用します</li><li><strong>入手</strong> または <strong>購入</strong> をクリックして購入します</li><li>アプリは自動的にダウンロードされインストールされます</li><li>アプリケーションフォルダまたは Launchpad から Sudoku を起動します</li></ol><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to “初回起動”">​</a></h2><p>Sudoku を初めて起動すると、iCloud（同期用）と Game Center（リーダーボードと実績用）へのアクセス許可が求められます。これらは任意です — 許可しなくてもゲームは完全にオフラインで動作します。</p><h2 id="アップデート" tabindex="-1">アップデート <a class="header-anchor" href="#アップデート" aria-label="Permalink to “アップデート”">​</a></h2><p>アップデートは App Store によって自動的に処理されます。手動で確認するには、App Store を開き、<strong>アカウント → アップデート</strong> のセクションに移動してください。</p><h2 id="アンインストール" tabindex="-1">アンインストール <a class="header-anchor" href="#アンインストール" aria-label="Permalink to “アンインストール”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Sudoku のアプリアイコンを長押しします</li><li><strong>App を削除</strong> → <strong>App を削除</strong> をタップします</li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Sudoku を終了します</li><li><code>Applications</code> から <code>Sudoku.app</code> をゴミ箱にドラッグします</li><li>（任意）アプリデータを削除します：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to “システム要件”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 以降</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）以降</li><li><strong>CPU</strong>：Apple Silicon（M シリーズ）</li><li><strong>メモリ</strong>：最低 2GB</li><li><strong>ストレージ</strong>：約 50 MB</li><li><strong>ネットワーク</strong>：ゲームプレイには不要（iCloud／Game Center は任意）</li></ul><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to “トラブルシューティング”">​</a></h2><p>インストール中に問題が発生した場合：</p><ul><li><strong>macOS がアプリをブロックする</strong>：<strong>システム設定 → プライバシーとセキュリティ</strong> を開き、Sudoku の <strong>このまま開く</strong> をクリックします</li><li><strong>アプリが表示されない</strong>：App Store アプリまたはデバイスを再起動して、もう一度お試しください</li></ul><p>さらに詳しい情報は<a href="./troubleshooting.html">トラブルシューティングガイド</a>をご覧いただくか、プロジェクトリポジトリで issue を作成してください。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};